    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Which of the following is an absolute contraindication to the placement of a central venous catheter at a specific site?', '["Severe coagulopathy", "Infection or burn overlying the insertion site", "Patient requires vasopressors", "History of deep vein thrombosis in the contralateral limb"]', 1, 'Inserting a needle through an infected area or burn will introduce bacteria directly into the central circulation. Coagulopathy is a relative contraindication (manageable with compressible sites).'),
    (v_topic_id, 'A patient with severe cirrhosis and an INR of 4.5 requires a central line for vasopressor administration. Which site is relatively CONTRAINDICATED due to the inability to compress bleeding?', '["Right Internal Jugular vein", "Left Internal Jugular vein", "Subclavian vein", "Femoral vein"]', 2, 'The subclavian vein runs under the clavicle, making it impossible to apply direct manual pressure in the event of an inadvertent arterial puncture or severe venous bleeding.'),
    (v_topic_id, 'Which central venous access site is generally associated with the lowest rate of catheter-related bloodstream infections (CRBSIs) but carries the highest risk of pneumothorax?', '["Femoral vein", "Internal Jugular vein", "Subclavian vein", "Antecubital vein (PICC)"]', 2, 'The subclavian site is relatively clean and easy to maintain, reducing infection risk, but its proximity to the pleural dome increases the risk of pneumothorax.'),
    (v_topic_id, 'Which central venous access site is considered the safest and most accessible during active cardiopulmonary resuscitation (CPR)?', '["Right Internal Jugular vein", "Subclavian vein", "Femoral vein", "Left Internal Jugular vein"]', 2, 'The femoral site allows the provider to work far away from the airway and chest compressions, avoiding interference with resuscitation efforts.'),
    (v_topic_id, 'Which central venous access site carries the highest overall risk of catheter-related bloodstream infections?', '["Right Internal Jugular vein", "Subclavian vein", "Femoral vein", "Peripherally Inserted Central Catheter (PICC)"]', 2, 'The femoral region has a higher bacterial load due to its proximity to the groin and perineum, leading to higher infection rates if left in place for extended periods.'),
    (v_topic_id, 'To recall the anatomy of the femoral triangle from lateral to medial, the mnemonic NAVEL is used. In this mnemonic, what does the "V" stand for?', '["Ventricle", "Vein", "Vastus lateralis", "Vagus"]', 1, 'From lateral to medial: Nerve (Femoral), Artery (Femoral), Vein (Femoral), Empty space (femoral canal), Lymphatics.'),
    (v_topic_id, 'When attempting a blind (landmark-based) right femoral central line, you palpate the femoral pulse. Where should you insert the needle relative to the pulse?', '["1 cm lateral to the pulse", "1 cm medial to the pulse", "Directly into the pulse", "Superior to the inguinal ligament"]', 1, 'The femoral vein lies immediately medial to the femoral artery (NAVEL: Nerve, Artery, Vein).'),
    (v_topic_id, 'What is the anatomical relationship of the Internal Jugular (IJ) vein to the Carotid Artery?', '["The IJ is medial to the carotid artery", "The IJ is posterior to the carotid artery", "The IJ is typically lateral and slightly anterior to the carotid artery", "The IJ is inferior to the carotid artery"]', 2, 'The IJ vein generally runs lateral and superficial (anterior) to the carotid artery within the carotid sheath.'),
    (v_topic_id, 'Which anatomical structure separates the Subclavian Vein (anteriorly) from the Subclavian Artery (posteriorly)?', '["Sternocleidomastoid muscle", "Anterior scalene muscle", "Clavicle", "First rib"]', 1, 'The anterior scalene muscle inserts on the first rib, passing exactly between the subclavian vein and the subclavian artery.'),
    (v_topic_id, 'Why is the Right Internal Jugular vein generally preferred over the Left Internal Jugular vein for central line placement?', '["The right IJ has a higher risk of pneumothorax", "The right IJ is larger in all patients", "The right IJ provides a straight, direct path to the Superior Vena Cava (SVC) and avoids the thoracic duct", "The left IJ is not compressible"]', 2, 'The right IJ offers a straight anatomical path down into the SVC and right atrium. The left IJ path is tortuous (requiring a turn at the brachiocephalic vein) and risks injuring the thoracic duct.'),
    (v_topic_id, 'A complication unique to left-sided neck central lines (Left IJ or Left Subclavian) is injury to the:', '["Recurrent laryngeal nerve", "Right atrium", "Thoracic duct (causing chylothorax)", "Azygos vein"]', 2, 'The thoracic duct, which carries chyle (lymph and fat), empties into the venous system at the junction of the left internal jugular and left subclavian veins.'),
    (v_topic_id, 'Before placing an Internal Jugular or Subclavian central line, the patient should be placed in the Trendelenburg position (head down). What is the primary purpose of this maneuver?', '["To prevent aspiration", "To distend the central veins and decrease the risk of air embolism", "To increase cardiac output", "To make the patient more comfortable"]', 1, 'Trendelenburg positioning uses gravity to increase venous return, distending the IJ and subclavian veins (making them easier to hit) and creating positive venous pressure to prevent air from being sucked in.'),
    (v_topic_id, 'What is the generally accepted appropriate depth of insertion for a Right Internal Jugular central line in an average adult to reach the cavoatrial junction?', '["5-7 cm", "15 cm", "20-22 cm", "25 cm"]', 1, 'A Right IJ line typically reaches the cavoatrial junction at around 15 cm. The Left IJ requires a slightly longer path, usually 17 cm.'),
    (v_topic_id, 'Where is the ideal anatomical location for the tip of a central venous catheter?', '["In the right ventricle", "In the superior vena cava, just above the cavoatrial junction", "In the innominate (brachiocephalic) vein", "In the pulmonary artery"]', 1, 'The ideal tip location is the lower third of the SVC, at or just above its junction with the right atrium (the cavoatrial junction), where blood flow is high and the risk of arrhythmias/perforation is low.'),
    (v_topic_id, 'After placing a Right Internal Jugular central line, a chest X-ray is obtained. What radiological landmark is used to confirm the tip is near the cavoatrial junction?', '["The aortic knob", "The right hemidiaphragm", "The carina / lower border of the right main bronchus", "The clavicle"]', 2, 'On a CXR, the cavoatrial junction roughly correlates with the inferior border of the right main bronchus or two vertebral bodies below the carina.'),
    (v_topic_id, 'Which of the following describes the fundamental principle of the Seldinger technique?', '["Using an ultrasound to visualize the needle tip", "Surgically exposing the vein before cannulation", "Passing a guidewire through a needle into a vessel, removing the needle, and then passing a catheter over the wire", "Using a balloon-tipped catheter to float into the pulmonary artery"]', 2, 'The Seldinger technique is the universal method for percutaneous vascular access: Needle -> Wire -> Dilator -> Catheter.'),
    (v_topic_id, 'During central line placement using the Seldinger technique, what is the most critical safety rule regarding the guidewire?', '["It must be pushed in until resistance is met", "Never let go of the guidewire; you must maintain control of it at all times", "Always leave the guidewire in the patient for future access", "The guidewire should be coated in heparin before insertion"]', 1, 'A "retained guidewire" (losing the wire entirely into the patient''s vascular system) is a severe, never-event medical error requiring interventional retrieval.'),
    (v_topic_id, 'When advancing the guidewire through the introducer needle into the vein, you meet significant resistance. What is the appropriate next step?', '["Push harder to overcome the obstruction", "Pull the needle and wire out together", "Stop advancing the wire, pull it back slightly, and reassess needle position (do not force it)", "Administer a fluid bolus"]', 2, 'Forcing a wire against resistance can cause vascular perforation, dissection, or kinking of the wire. The wire must always slide smoothly.'),
    (v_topic_id, 'What is the purpose of the tissue dilator in the Seldinger technique?', '["To expand the vein to hold more volume", "To create a larger tract through the skin and subcutaneous tissue to allow smooth passage of the soft catheter", "To break up blood clots in the vein", "To secure the catheter to the skin"]', 1, 'The dilator expands the small needle hole in the tough skin and fascia, allowing the larger, blunt-tipped central catheter to slide in without bending.'),
    (v_topic_id, 'During a landmark-based central line attempt, you obtain a "flash" of blood in the syringe. Which characteristic is most suggestive of an accidental arterial puncture rather than venous access?', '["Dark, sluggish blood", "Bright red, pulsatile, high-pressure blood flow that pushes the plunger back", "Blood that clots quickly in the syringe", "A very small amount of blood"]', 1, 'Arterial blood is under high pressure (pulsatile) and fully oxygenated (bright red). However, in severe shock/hypoxia, arterial blood may appear dark and non-pulsatile.'),
    (v_topic_id, 'You accidentally puncture the carotid artery with the small introducer (finder) needle. What is the correct management?', '["Leave the needle in and insert the guidewire", "Remove the needle and apply firm manual pressure for at least 10 minutes", "Proceed with placing the central line in the artery", "Perform an immediate cutdown"]', 1, 'If only the small needle has punctured the artery, simply removing it and holding pressure is usually sufficient to prevent a hematoma.'),
    (v_topic_id, 'You have placed a 7-French central line catheter into a vessel. Blood gas analysis from the catheter reveals it is in the carotid artery. What is the correct management?', '["Pull the catheter out immediately and hold pressure", "Administer protamine", "Leave the catheter IN PLACE and immediately consult vascular surgery", "Inject epinephrine through the catheter"]', 2, 'Pulling a large-bore catheter (7 French or larger) out of a non-compressible or major artery can lead to catastrophic, uncontrollable hemorrhage or airway compromise from a massive hematoma. Leave it in and get a surgeon.'),
    (v_topic_id, 'During central line insertion, the hub of the needle/catheter is left open to the air while the patient takes a deep breath. The patient suddenly becomes profoundly hypotensive and hypoxic. What complication has likely occurred?', '["Tension pneumothorax", "Massive pulmonary embolism", "Venous air embolism", "Anaphylaxis"]', 2, 'Negative intrathoracic pressure during inspiration can suck a large volume of air through an open needle hub directly into the right heart, causing an air-lock (air embolism) that halts pulmonary blood flow.'),
    (v_topic_id, 'A patient is suspected of having a large venous air embolism during central line placement. What is the traditional initial positioning maneuver (Durant''s maneuver) to manage this?', '["Right lateral decubitus and reverse Trendelenburg", "Left lateral decubitus (left side down) and Trendelenburg (head down)", "Supine with legs elevated", "Sitting upright"]', 1, 'This position attempts to keep the air bubble trapped in the apex of the right ventricle, preventing it from occluding the right ventricular outflow tract (pulmonary valve).'),
    (v_topic_id, 'While advancing the guidewire during a right Internal Jugular central line, the cardiac monitor suddenly shows a run of premature ventricular contractions (PVCs) and non-sustained ventricular tachycardia. What is the cause?', '["Myocardial infarction", "The wire has been advanced too far and is irritating the endocardium of the right ventricle", "Electrolyte imbalance", "Air embolism"]', 1, 'Mechanical irritation of the right ventricular endocardium by the guidewire frequently causes arrhythmias.'),
    (v_topic_id, 'What is the immediate treatment for guidewire-induced arrhythmias during central line placement?', '["Administer Amiodarone", "Defibrillate the patient", "Pull the guidewire back a few centimeters until the arrhythmia resolves", "Administer Epinephrine"]', 2, 'Simply withdrawing the wire from the right ventricle back into the SVC almost always resolves the mechanically induced arrhythmia immediately.'),
    (v_topic_id, 'When using the landmark (infraclavicular) approach to the Subclavian vein, the needle is inserted just inferior to the clavicle. Where should the needle tip be aimed?', '["Toward the ipsilateral nipple", "Toward the sternal notch", "Straight down into the chest", "Toward the patient''s chin"]', 1, 'Aiming for the sternal notch keeps the needle parallel to the chest wall, guiding it under the clavicle toward the vein while minimizing the risk of aiming too deep into the pleura.'),
    (v_topic_id, 'The classic landmark for the Internal Jugular vein approach is the apex of Sedillot''s triangle. What muscles form this triangle?', '["The two heads (sternal and clavicular) of the Sternocleidomastoid muscle and the clavicle", "The anterior scalene, middle scalene, and first rib", "The trapezius, sternocleidomastoid, and clavicle", "The digastric, omohyoid, and mandible"]', 0, 'Sedillot''s triangle is formed by the sternal head of the SCM medially, the clavicular head laterally, and the clavicle inferiorly. The IJ runs right through the center of this triangle.'),
    (v_topic_id, 'Which of the following is a major advantage of using Point-of-Care Ultrasound (POCUS) for Internal Jugular vein cannulation compared to the blind landmark technique?', '["It completely eliminates the risk of infection", "It decreases the number of attempts, the time to cannulation, and the complication rate (e.g., arterial puncture)", "It allows for a smaller catheter to be used", "It replaces the need for a post-procedure chest X-ray"]', 1, 'Ultrasound guidance is the standard of care for IJ placement because visualizing the needle entering the vein dramatically improves success rates and safety.'),
    (v_topic_id, 'When differentiating a vein from an artery using ultrasound, which characteristic confirms the vessel is a vein?', '["It is thick-walled", "It is brightly echogenic (white)", "It is perfectly round and pulsatile", "It is thin-walled and completely compressible with probe pressure"]', 3, 'Veins have low pressure and thin walls, so gentle downward pressure with the ultrasound probe easily collapses them. Arteries will remain round and pulsate.'),
    (v_topic_id, 'During ultrasound evaluation, a patient in hypovolemic shock will typically have an Internal Jugular vein that:', '["Is massive and non-compressible", "Is completely flat or ''kissing'' (walls touching) during inspiration", "Pulsates vigorously", "Appears identical to the carotid artery"]', 1, 'Hypovolemia leads to low central venous pressure. Negative intrathoracic pressure during inspiration easily collapses these under-filled veins.'),
    (v_topic_id, 'A central line measures Central Venous Pressure (CVP), which is an estimate of right atrial pressure and right ventricular preload. What is a normal CVP value?', '["0-2 mmHg", "8-12 mmHg", "20-25 mmHg", "40-50 mmHg"]', 1, 'Normal CVP in a spontaneously breathing patient is roughly 8-12 mmHg. Extremes indicate profound hypovolemia (low) or fluid overload/right heart failure (high).'),
    (v_topic_id, 'Which of the following is a strong clinical indication for placing a central venous catheter instead of a peripheral IV?', '["Administration of 1 liter of Normal Saline", "Administration of a single dose of Ceftriaxone", "Administration of highly concentrated vasoactive drugs (e.g., Norepinephrine) or Total Parenteral Nutrition (TPN)", "Drawing basic routine blood labs"]', 2, 'Vasopressors can cause severe tissue necrosis if they extravasate from a peripheral IV. TPN is highly hyperosmolar and will cause phlebitis in small veins. Both require central delivery.'),
    (v_topic_id, 'In a cardiac arrest (Code Blue) situation where the patient has no IV access, what is the fastest and most preferred method to obtain vascular access for pushing epinephrine?', '["Subclavian central line", "Intraosseous (IO) line", "Internal Jugular central line", "Femoral central line"]', 1, 'An IO line can be established in less than 10 seconds, whereas placing a central line during CPR is difficult, time-consuming, and prone to complications.'),
    (v_topic_id, 'Which of the following sites is the most commonly used for Intraosseous (IO) access in adults?', '["Proximal tibia", "Distal radius", "Sternum", "Calcaneus"]', 0, 'The proximal tibia (anteromedial surface, 2 cm below the tibial tuberosity) is the most standard, easily accessible, and easily identified IO site.'),
    (v_topic_id, 'According to Poiseuille''s Law, the flow rate of a fluid through a tube is proportional to the radius to the 4th power and inversely proportional to length. Based on this, which catheter delivers a massive fluid resuscitation FASTEST?', '["A long, 7-French triple-lumen central venous catheter", "A short, large-bore 14-gauge peripheral IV", "A standard 20-gauge peripheral IV", "A PICC line"]', 1, 'A short, wide tube (like a 14G peripheral IV or a Cordis introducer) has exponentially less resistance and much faster flow rates than the long, narrow lumens of a standard triple-lumen central line.'),
    (v_topic_id, 'What is a "Cordis" (Introducer Sheath) primarily designed for in the emergency department setting?', '["Measuring continuous blood pressure", "Massive, rapid volume transfusion in severe hemorrhagic shock", "Long-term outpatient antibiotic therapy", "Parenteral nutrition"]', 1, 'An introducer sheath is a very large bore (e.g., 8.5 French), short catheter. Due to its large radius and short length, it allows for massive, rapid fluid and blood resuscitation.'),
    (v_topic_id, 'To adhere to "Maximal Sterile Barrier Precautions" during central line placement and prevent infection, the operator must wear:', '["Just sterile gloves", "Sterile gloves and a mask", "A mask, cap, sterile gown, sterile gloves, and use a full-body sterile drape", "A sterile gown and gloves only"]', 2, 'Full maximal sterile barriers are proven to significantly reduce the risk of Catheter-Related Bloodstream Infections (CRBSIs).'),
    (v_topic_id, 'Which antiseptic solution is considered superior and is the standard of care for skin preparation prior to central line insertion?', '["70% Isopropyl alcohol", "Povidone-Iodine (Betadine)", "2% Chlorhexidine with 70% isopropyl alcohol", "Hydrogen peroxide"]', 2, 'Chlorhexidine provides superior, longer-lasting antimicrobial coverage compared to povidone-iodine. It must be allowed to dry completely to be effective.'),
    (v_topic_id, 'A PICC (Peripherally Inserted Central Catheter) line is typically inserted into which vein in the arm?', '["Femoral vein", "Basilic or Cephalic vein", "Radial vein", "Subclavian vein"]', 1, 'PICC lines are inserted into the deep veins of the upper arm (basilic, cephalic, or brachial) and threaded all the way into the Superior Vena Cava.'),
    (v_topic_id, 'Which of the following accurately describes the "in-plane" approach when using ultrasound for vascular access?', '["The needle crosses the ultrasound beam at a 90-degree angle, appearing as a single white dot", "The entire length of the needle, including the shaft and tip, is visualized continuously as it approaches the vessel", "The ultrasound probe is placed parallel to the ribs", "The operator uses landmarks only, without looking at the screen"]', 1, 'The in-plane approach aligns the needle exactly with the long axis of the ultrasound probe, allowing the operator to see the entire needle and its tip at all times.'),
    (v_topic_id, 'A patient receives a Left Subclavian central line. An hour later, they develop respiratory distress, and a chest tube is placed. The chest tube drains a milky-white fluid. What complication has occurred?', '["Hemothorax", "Empyema", "Chylothorax due to thoracic duct injury", "Pneumothorax"]', 2, 'The thoracic duct arches up into the left neck before emptying into the junction of the left IJ and subclavian veins. Injury releases chyle (milky lymphatic fluid containing fat) into the chest.'),
    (v_topic_id, 'Which component of a standard central line kit is used to enlarge the entry site at the skin AFTER the guidewire is in place, but BEFORE the dilator is used?', '["The introducer needle", "The scalpel (number 11 blade)", "The suture", "The syringe"]', 1, 'A small "nick" is made in the skin with a scalpel right where the guidewire enters, which prevents the tough skin from catching and damaging the dilator or catheter.'),
    (v_topic_id, 'A patient requires emergency dialysis, but no fistula is present. A "Quinton" or dialysis catheter must be placed. How does a dialysis catheter differ mechanically from a standard triple-lumen CVC?', '["It is much longer", "It has very small lumens to restrict flow", "It has two large-bore lumens capable of high flow rates (300-400 mL/min) and is stiffer", "It is inserted directly into the radial artery"]', 2, 'Dialysis requires pulling and returning massive amounts of blood per minute. The catheter is thick, stiff, and has two large lumens (one for pulling blood to the machine, one for returning it).'),
    (v_topic_id, 'During the placement of a central line, the operator inadvertently drops the syringe, leaving the introducer needle in the vein open to the air. The patient is breathing spontaneously. Why is this highly dangerous?', '["It will cause a massive hemorrhage", "Spontaneous inspiration creates negative intrathoracic pressure, sucking air into the vein and causing an air embolism", "It guarantees an infection", "It will cause the needle to fall out"]', 1, 'Negative intrathoracic pressure from spontaneous breathing acts like a vacuum, pulling air through the open needle hub directly into the heart.'),
    (v_topic_id, 'Which of the following indicates that a patient is too hypovolemic for a safe Internal Jugular central line placement?', '["The vein is 2 cm in diameter", "The vein completely collapses with every breath on ultrasound", "The patient has a normal blood pressure", "The CVP is 15 mmHg"]', 1, 'A completely collapsible ("kissing") vein means there is very little volume. Attempting to puncture it often results in passing the needle completely through both walls (through-and-through puncture) and hitting the artery below.'),
    (v_topic_id, 'In an emergency, if you cannot flush or draw blood from one port of a newly placed triple-lumen catheter, what is the most likely mechanical reason?', '["The port is infected", "The lumen is kinked or the tip is resting against the vessel wall", "The patient is hypovolemic", "The catheter is in an artery"]', 1, 'If a catheter is inserted properly but won''t draw blood, the tip may be wedged against the wall of the SVC. Pulling it back 1-2 cm often resolves the issue.'),
    (v_topic_id, 'When securing a central venous catheter to the skin, which method is considered the standard of care to prevent accidental dislodgement?', '["Medical tape only", "A single suture through the skin, tied around the catheter", "Suturing the catheter hub to the skin in at least two places, followed by a sterile occlusive dressing", "Cyanoacrylate glue"]', 2, 'Suturing the catheter ears to the skin and covering with a sterile, transparent, occlusive dressing (e.g., Tegaderm) secures the line and prevents infection.'),
    (v_topic_id, 'Before using any lumen of a newly placed internal jugular or subclavian central line for vasopressors, what MUST be done if ultrasound was not used to confirm the tip location?', '["Flush it with 50 mL of saline", "Obtain a portable chest X-ray to confirm tip placement and rule out pneumothorax", "Administer a test dose of Epinephrine", "Draw a venous blood gas"]', 1, 'A CXR is mandatory to ensure the tip is not in the wrong vessel (e.g., up the jugular or in an artery) and to ensure a pneumothorax was not caused during the procedure.');
